targets.query:
from(bucket: "loxone") |> range(start: v.timeRangeStart, stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "loxone" and r._field == "value" and r.type == "Switch" and r.room =~ /^${room:regex}$/)
  |> map(fn: (r) => ({r with _field: r.room + " " + r.control}))
  |> keep(columns: ["_time", "_value", "_field"])
